  "d.1yawpsx": "MINIGUNA",
  "d.1yg6jc4": "Reditus adhibetur ad plures homines conducendos et inceptum amplificandum.",
  "d.1yq2qk7": "THETA-7 ASTEROID FIELD, imago sectoris ex indice ludi. Captio ex ludo, versio 0.6.1",
